/**
 * PhysicsWeapons - Unified weapon system for hitscan, projectile, and hybrid weapons
 *
 * Provides a single API for all weapon types:
 * - **HITSCAN**: Instant raycast damage (rifles, pistols, lasers)
 * - **PROJECTILE**: Traveling physics-based (arrows, grenades, rockets)
 * - **HYBRID**: Instant damage + visual projectile travel (competitive FPS feel)
 *
 * All weapon types emit the same `hit` event with weapon-specific metadata.
 * Attached as a singleton to Physics as `physics.weapons`.
 *
 * **Usage**
 *
 * ```js
 * import { Physics, WeaponType, ProjectilePreset } from '@three-blocks/pro';
 *
 * const physics = new Physics();
 * await physics.init();
 *
 * // Hitscan rifle
 * physics.weapons.fire(shooterIndex, {
 *   type: WeaponType.HITSCAN,
 *   bodyType: 'dynamic',
 *   direction: [0, 0, 1],
 *   damage: 25,
 * });
 *
 * // Projectile arrow from tower
 * physics.weapons.fire(towerIndex, {
 *   type: WeaponType.PROJECTILE,
 *   bodyType: 'kinematic',
 *   direction: aimDir,
 *   damage: 30,
 *   ...ProjectilePreset.ARROW,
 * });
 *
 * // Hybrid (instant hit + visual bullet)
 * physics.weapons.fire(shooterIndex, {
 *   type: WeaponType.HYBRID,
 *   bodyType: 'dynamic',
 *   direction: forward,
 *   damage: 20,
 *   projectileSpeed: 200,
 * });
 *
 * // Fire from camera (FPS crosshair)
 * physics.weapons.fireFromCamera({
 *   type: WeaponType.HITSCAN,
 *   shooterIndex: 0,
 *   damage: 25,
 * });
 *
 * // Listen for hits (same event for all weapon types)
 * npcApi.body.addEventListener('hit', (event) => {
 *   console.log(`Hit by ${event.weaponType} for ${event.damage} damage`);
 * });
 * ```
 *
 * **Terminology**
 *
 * | Term | Definition |
 * |------|------------|
 * | Hitscan | Instant raycast weapon (no travel time) |
 * | Projectile | Traveling physics-based weapon |
 * | Hybrid | Instant hit + visual projectile |
 * | Shooter | Body that fires the weapon |
 * | Target | Body that receives the hit |
 * | AoE | Area of Effect (splash damage radius) |
 *
 * @class PhysicsWeapons
 * @short Unified weapon system for hitscan, projectile, and hybrid weapons
 * @category Weapons
 * @tags Physics, Weapons, WebGPU, WebGL
 *
 * @see {@link Physics} - Main physics API that exposes this as `physics.weapons`
 * @see {@link WeaponType} - Enum for weapon types
 * @see {@link ProjectilePreset} - Preset configurations for projectiles
 */
export class PhysicsWeapons {
    /**
     * Create a PhysicsWeapons instance.
     * @param {Object} sharedViews - Shared buffer views
     * @param {Float32Array} sharedViews.weapons - Weapon request buffer
     * @param {ArrayOfBufferBackedObjects} sharedViews.projectiles - Projectile pool buffer
     * @param {ArrayOfBufferBackedObjects} sharedViews.dynamic - Dynamic bodies buffer
     * @param {ArrayOfBufferBackedObjects} sharedViews.kinematic - Kinematic bodies buffer
     * @param {Physics} physics - Physics instance for worker access
     */
    constructor(sharedViews: {
        weapons: Float32Array;
        projectiles: ArrayOfBufferBackedObjects;
        dynamic: ArrayOfBufferBackedObjects;
        kinematic: ArrayOfBufferBackedObjects;
    }, physics: Physics);
    _sharedWeapons: Float32Array<ArrayBufferLike>;
    _sharedProjectiles: ArrayOfBufferBackedObjects;
    _sharedDynamic: ArrayOfBufferBackedObjects;
    _sharedKinematic: ArrayOfBufferBackedObjects;
    _physics: Physics;
    _onExplodeHandlers: any[];
    /**
     * Subscribe to projectile explosion events.
     * Listens for all projectile detonations (collision or timeout).
     *
     * @param {Function} callback - Called with explosion event data
     * @returns {Function} Unsubscribe function
     *
     * @example
     * ```js
     * const unsubscribe = physics.weapons.onExplode((explosion) => {
     *   console.log(`Explosion at [${explosion.position.x}, ${explosion.position.y}, ${explosion.position.z}]`);
     *   console.log(`Cause: ${explosion.cause}, Radius: ${explosion.aoeRadius}m`);
     *
     *   // Spawn visual effects
     *   spawnExplosionVFX(explosion.position, explosion.aoeRadius);
     * });
     *
     * // Cleanup when done
     * unsubscribe();
     * ```
     */
    onExplode(callback: Function): Function;
    /**
     * Fire a weapon from a body's position.
     *
     * @param {number|Object} shooter - Body index or body API object (from physics.addBody)
     * @param {Object} options - Fire options
     * @param {string} [options.type='hitscan'] - Weapon type: 'hitscan', 'projectile', or 'hybrid'
     * @param {THREE.Vector3|number[]} options.direction - Fire direction as Vector3 or [x, y, z]
     * @param {THREE.Vector3|number[]} [options.origin] - Override origin position as Vector3 or [x, y, z], defaults to body position
     * @param {number} [options.maxDistance=1000] - Maximum raycast distance (hitscan/hybrid)
     * @param {boolean} [options.piercing=false] - If true, ray passes through all targets (hitscan only)
     * @param {number} [options.damage=10] - Damage value
     * @param {number} [options.speed=40] - Projectile speed in m/s (projectile/hybrid)
     * @param {number} [options.gravity=1] - Gravity multiplier (projectile)
     * @param {number} [options.drag=0.01] - Drag coefficient (projectile)
     * @param {number} [options.lifetime=5] - Projectile lifetime in seconds
     * @param {number} [options.aoeRadius=0] - Area of effect radius (0 = point hit)
     *
     * @example
     * ```js
     * // Using body API directly (recommended)
     * physics.weapons.fire(playerApi, {
     *   direction: aimDir,
     *   damage: 25,
     * });
     *
     * // Using body index (legacy)
     * physics.weapons.fire(playerApi.index, {
     *   type: WeaponType.HITSCAN,
     *   bodyType: 'dynamic',
     *   direction: [0, 0, 1],
     *   damage: 25,
     * });
     * ```
     */
    fire(shooter: number | any, options?: {
        type?: string;
        direction: THREE.Vector3 | number[];
        origin?: THREE.Vector3 | number[];
        maxDistance?: number;
        piercing?: boolean;
        damage?: number;
        speed?: number;
        gravity?: number;
        drag?: number;
        lifetime?: number;
        aoeRadius?: number;
    }): void;
    /**
     * Fire a weapon from the camera center (crosshair).
     * This is the most common firing method for FPS games.
     *
     * @param {Object} [options] - Fire options
     * @param {string} [options.type='hitscan'] - Weapon type: 'hitscan', 'projectile', or 'hybrid'
     * @param {number} [options.shooterIndex=0] - Index of the body considered the shooter
     * @param {string} [options.shooterType='dynamic'] - Shooter body type ('dynamic' or 'kinematic')
     * @param {number} [options.maxDistance=1000] - Maximum raycast distance
     * @param {boolean} [options.piercing=false] - If true, ray passes through all targets
     * @param {number} [options.damage=10] - Damage value
     * @param {number} [options.speed=40] - Projectile speed in m/s (projectile/hybrid)
     * @param {number} [options.gravity=1] - Gravity multiplier (projectile)
     * @param {number} [options.drag=0.01] - Drag coefficient (projectile)
     * @param {number} [options.lifetime=5] - Projectile lifetime in seconds
     * @param {number} [options.aoeRadius=0] - Area of effect radius (0 = point hit)
     * @param {boolean} [options.explodeOnContact] - If true, projectile explodes on collision. Defaults to true if aoeRadius > 0
     *
     * @example
     * ```js
     * // Hitscan from crosshair
     * physics.weapons.fireFromCamera({
     *   type: WeaponType.HITSCAN,
     *   shooterIndex: 0,
     *   damage: 25,
     * });
     *
     * // Hybrid rifle (instant hit + visual bullet)
     * physics.weapons.fireFromCamera({
     *   type: WeaponType.HYBRID,
     *   shooterIndex: 0,
     *   damage: 20,
     *   speed: 200, // Visual projectile speed
     * });
     * ```
     */
    fireFromCamera(options?: {
        type?: string;
        shooterIndex?: number;
        shooterType?: string;
        maxDistance?: number;
        piercing?: boolean;
        damage?: number;
        speed?: number;
        gravity?: number;
        drag?: number;
        lifetime?: number;
        aoeRadius?: number;
        explodeOnContact?: boolean;
    }): void;
    /**
     * Fire an arrow projectile. Convenience method with arrow defaults.
     *
     * @param {number|Object} shooter - Body index or body API object (from physics.addBody)
     * @param {Object} options - Fire options
     * @param {THREE.Vector3|number[]} options.direction - Fire direction as Vector3 or [x, y, z]
     * @param {THREE.Vector3|number[]} [options.origin] - Override origin position as Vector3 or [x, y, z]
     * @param {number} [options.damage=25] - Damage value
     * @param {number} [options.speed=40] - Arrow speed in m/s
     *
     * @example
     * ```js
     * physics.weapons.fireArrow(towerApi, {
     *   direction: aimDir,
     *   damage: 30,
     * });
     * ```
     */
    fireArrow(shooter: number | any, options?: {
        direction: THREE.Vector3 | number[];
        origin?: THREE.Vector3 | number[];
        damage?: number;
        speed?: number;
    }): void;
    /**
     * Fire a grenade with AoE damage. Convenience method with grenade defaults.
     *
     * @param {number|Object} shooter - Body index or body API object (from physics.addBody)
     * @param {Object} options - Fire options
     * @param {THREE.Vector3|number[]} options.direction - Throw direction as Vector3 or [x, y, z]
     * @param {THREE.Vector3|number[]} [options.origin] - Override origin position as Vector3 or [x, y, z]
     * @param {number} [options.damage=100] - Damage value at center
     * @param {number} [options.aoeRadius=5] - Explosion radius
     * @param {number} [options.speed=15] - Throw speed in m/s
     *
     * @example
     * ```js
     * physics.weapons.fireGrenade(playerApi, {
     *   direction: throwDir,
     *   damage: 100,
     *   aoeRadius: 5,
     * });
     * ```
     */
    fireGrenade(shooter: number | any, options?: {
        direction: THREE.Vector3 | number[];
        origin?: THREE.Vector3 | number[];
        damage?: number;
        aoeRadius?: number;
        speed?: number;
    }): void;
    /**
     * Fire a rocket with AoE damage. Convenience method with rocket defaults.
     *
     * @param {number|Object} shooter - Body index or body API object (from physics.addBody)
     * @param {Object} options - Fire options
     * @param {THREE.Vector3|number[]} options.direction - Fire direction as Vector3 or [x, y, z]
     * @param {THREE.Vector3|number[]} [options.origin] - Override origin position as Vector3 or [x, y, z]
     * @param {number} [options.damage=75] - Damage value at center
     * @param {number} [options.aoeRadius=3] - Explosion radius
     *
     * @example
     * ```js
     * physics.weapons.fireRocket(playerApi, {
     *   direction: aimDir,
     *   damage: 75,
     * });
     * ```
     */
    fireRocket(shooter: number | any, options?: {
        direction: THREE.Vector3 | number[];
        origin?: THREE.Vector3 | number[];
        damage?: number;
        aoeRadius?: number;
    }): void;
}
